import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract watermark scalar
    high_ts = watermark["high_ts"].iloc[0]

    # Build current state dict keyed by user_id
    state = {}
    for _, row in target_snapshot.iterrows():
        state[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    # Filter events strictly after the watermark
    events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort globally by (event_ts, event_seq) to apply sequentially and
    # deterministically; this also gives correct per-user ordering.
    events = events.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    seven_days = timedelta(days=7)

    for _, ev in events.iterrows():
        user_id = ev["user_id"]
        op = ev["op"]
        ev_email = ev["email"]
        ev_ts = ev["event_ts"]

        current = state.get(user_id)

        if current is None:
            # New user not present in target snapshot
            if op == "U":
                state[user_id] = {
                    "email": ev_email,
                    "status": "ACTIVE",
                    "status_ts": ev_ts,
                }
            elif op == "D":
                # No prior row to preserve email from; use event's email.
                state[user_id] = {
                    "email": ev_email,
                    "status": "DELETED",
                    "status_ts": ev_ts,
                }
            continue

        cur_status = current["status"]
        cur_status_ts = current["status_ts"]
        cur_email = current["email"]

        if op == "D":
            # Soft delete: email preserved as of deletion, status set to DELETED
            state[user_id] = {
                "email": cur_email,
                "status": "DELETED",
                "status_ts": ev_ts,
            }
        elif op == "U":
            if cur_status == "DELETED":
                # Resurrection only if strictly more than 7 days after deletion ts
                if ev_ts > (cur_status_ts + seven_days):
                    state[user_id] = {
                        "email": ev_email,
                        "status": "ACTIVE",
                        "status_ts": ev_ts,
                    }
                # else: discard the update, sticky deletion window
            else:
                # ACTIVE user upsert
                state[user_id] = {
                    "email": ev_email,
                    "status": "ACTIVE",
                    "status_ts": ev_ts,
                }

    # Build output dataframe
    out_rows = []
    for user_id, vals in state.items():
        out_rows.append(
            {
                "user_id": user_id,
                "email": vals["email"],
                "status": vals["status"],
                "status_ts": vals["status_ts"],
            }
        )

    new_snapshot = pd.DataFrame(
        out_rows, columns=["user_id", "email", "status", "status_ts"]
    )

    return {"new_snapshot": new_snapshot}
